import java.util.*;

class Solution {
    private int rows, cols;

    public void solve(char[][] board) {
        if (board == null || board.length == 0 || board[0].length == 0) return;
        rows = board.length;
        cols = board[0].length;

        for (int c = 0; c < cols; c++) {
            if (board[0][c] == 'O') dfs(board, 0, c);
            if (board[rows - 1][c] == 'O') dfs(board, rows - 1, c);
        }
        for (int r = 0; r < rows; r++) {
            if (board[r][0] == 'O') dfs(board, r, 0);
            if (board[r][cols - 1] == 'O') dfs(board, r, cols - 1);
        }

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == 'O') board[r][c] = 'X';
                else if (board[r][c] == 'S') board[r][c] = 'O';
            }
        }
    }

    private void dfs(char[][] board, int r, int c) {
        if (r < 0 || r >= rows || c < 0 || c >= cols) return;
        if (board[r][c] != 'O') return;
        board[r][c] = 'S';
        dfs(board, r + 1, c);
        dfs(board, r - 1, c);
        dfs(board, r, c + 1);
        dfs(board, r, c - 1);
    }
}

import java.util.*;

class Solution {
    private static final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public void solve(char[][] board) {
        if (board == null || board.length == 0 || board[0].length == 0) return;
        int rows = board.length;
        int cols = board[0].length;
        Deque<int[]> queue = new ArrayDeque<>();

        for (int c = 0; c < cols; c++) {
            if (board[0][c] == 'O') { board[0][c] = 'S'; queue.add(new int[]{0, c}); }
            if (board[rows - 1][c] == 'O') { board[rows - 1][c] = 'S'; queue.add(new int[]{rows - 1, c}); }
        }
        for (int r = 0; r < rows; r++) {
            if (board[r][0] == 'O') { board[r][0] = 'S'; queue.add(new int[]{r, 0}); }
            if (board[r][cols - 1] == 'O') { board[r][cols - 1] = 'S'; queue.add(new int[]{r, cols - 1}); }
        }

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            for (int[] d : DIRS) {
                int nr = cur[0] + d[0];
                int nc = cur[1] + d[1];
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
                if (board[nr][nc] != 'O') continue;
                board[nr][nc] = 'S';
                queue.add(new int[]{nr, nc});
            }
        }

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == 'O') board[r][c] = 'X';
                else if (board[r][c] == 'S') board[r][c] = 'O';
            }
        }
    }
}

import java.util.*;

class Solution {
    private int[] parent;

    public void solve(char[][] board) {
        if (board == null || board.length == 0 || board[0].length == 0) return;
        int m = board.length;
        int n = board[0].length;
        int virtual = m * n;

        parent = new int[m * n + 1];
        Arrays.fill(parent, -1);
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (board[r][c] == 'O') parent[r * n + c] = r * n + c;
            }
        }
        parent[virtual] = virtual;

        for (int c = 0; c < n; c++) {
            if (board[0][c] == 'O') union(c, virtual);
            if (board[m - 1][c] == 'O') union((m - 1) * n + c, virtual);
        }
        for (int r = 0; r < m; r++) {
            if (board[r][0] == 'O') union(r * n, virtual);
            if (board[r][n - 1] == 'O') union(r * n + n - 1, virtual);
        }

        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (board[r][c] != 'O') continue;
                int id = r * n + c;
                if (c + 1 < n && board[r][c + 1] == 'O') union(id, id + 1);
                if (r + 1 < m && board[r + 1][c] == 'O') union(id, id + n);
            }
        }

        int rootVirtual = find(virtual);
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (board[r][c] != 'O') continue;
                if (find(r * n + c) != rootVirtual) board[r][c] = 'X';
            }
        }
    }

    private int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }

    private void union(int a, int b) {
        int ra = find(a);
        int rb = find(b);
        if (ra != rb) parent[ra] = rb;
    }
}
